// Only the synthetic company generated by recipes-smoke.cjs.
const { chromium } = require("../work/browser/node_modules/playwright");
const fs = require("node:fs"),
  assert = require("node:assert/strict");
const { client, rootUrl } = require("./testing/commercial-context.cjs");
(async () => {
  const f = JSON.parse(fs.readFileSync("work/recipes/fixture.json")),
    { request } = client();
  const login = await request("/auth/login", {
    method: "POST",
    body: { company: f.company, username: f.username, password: f.password },
  });
  const api = (path, method = "GET", body) =>
    request(path, { method, body, token: login.token });
  const b = await chromium.launch({
    executablePath: "/usr/bin/chromium",
    args: ["--no-sandbox"],
  });
  let checks = 0;
  const errors = [];
  try {
    const c = await b.newContext({ viewport: { width: 1440, height: 1080 } });
    await c.addInitScript((s) => {
      localStorage.setItem("token", s.token);
      localStorage.setItem("user", JSON.stringify(s.user));
      localStorage.setItem("company", s.user.company);
    }, login);
    const p = await c.newPage();
    p.on("pageerror", (e) => errors.push(e.message));
    p.on("dialog", (d) => d.accept());
    await p.goto(rootUrl + "/recipes");
    await p
      .getByLabel("Produto preparado", { exact: true })
      .selectOption(f.burgerId);
    await p.getByLabel("Rendimento", { exact: true }).fill("1");
    for (const button of await p
      .getByRole("button", { name: "Remover insumo", exact: true })
      .all())
      await button.click();
    await p.getByLabel("Insumo", { exact: true }).selectOption(f.breadId);
    await p
      .getByRole("button", { name: "Adicionar insumo", exact: true })
      .click();
    await p.getByLabel("Quantidade de Pão unidade", { exact: true }).fill("1");
    await p
      .getByRole("button", { name: "Salvar ficha técnica", exact: true })
      .click();
    await p
      .getByRole("status")
      .filter({ hasText: "Ficha técnica salva." })
      .waitFor();
    checks++;
    const definition = (await api("/recipes")).find(
      (r) => r.productId === f.burgerId,
    );
    assert.equal(definition.ingredients[0].productId, f.breadId);
    checks++;
    await p.screenshot({
      path: "work/recipes/ficha-tecnica.png",
      fullPage: true,
    });
    const before = Number(
      (await api("/products")).find((p) => p.id === f.breadId).currentStock,
    );
    await p.goto(rootUrl + "/sales");
    await p
      .getByPlaceholder("Buscar produtos...", { exact: true })
      .fill("Hambúrguer preparado");
    const card = p
      .getByRole("heading", { name: "Hambúrguer preparado", exact: true })
      .locator('xpath=ancestor::div[@data-slot="card"][1]');
    await card.getByText(/Ficha técnica · disponível:/).waitFor();
    await card.getByRole("button").click();
    await p.getByRole("button", { name: /^Carrinho \(/ }).click();
    const d = p
      .getByRole("dialog")
      .filter({
        has: p.getByRole("heading", { name: "Finalizar Venda", exact: true }),
      });
    await d
      .getByRole("button", { name: "Finalizar Venda", exact: true })
      .click();
    await d.waitFor({ state: "hidden" });
    checks++;
    const latest = (await api("/sales"))[0];
    assert.equal(latest.items[0].recipe.plan.revision, definition.revision);
    assert.equal(
      Number(
        (await api("/products")).find((p) => p.id === f.breadId).currentStock,
      ),
      before - 1,
    );
    checks++;
    await p.goto(rootUrl + "/kitchen");
    await p
      .getByRole("heading", {
        name: "Preparados do balcão — vendas pagas",
        exact: true,
      })
      .waitFor();
    const order = p
      .locator("article")
      .filter({ hasText: "Venda #" + latest.id });
    await order
      .getByRole("button", { name: "Iniciar preparo", exact: true })
      .click();
    await order
      .getByRole("button", { name: "Marcar pronta", exact: true })
      .waitFor();
    checks++;
    await p.goto(rootUrl + "/recipes");
    await p
      .getByLabel("Produto preparado", { exact: true })
      .selectOption(f.burgerId);
    await p.setViewportSize({ width: 390, height: 844 });
    assert.ok(
      await p
        .locator("main")
        .evaluate((e) => e.scrollWidth <= e.clientWidth + 1),
    );
    await p.screenshot({ path: "work/recipes/celular.png", fullPage: true });
    checks++;
    assert.deepEqual(errors, []);
    console.log(
      checks +
        " verificações de navegador aprovadas: edição de receita, custo, venda, baixa de insumo, cozinha e celular; sem erros JavaScript.",
    );
  } finally {
    await b.close();
  }
})().catch((e) => {
  console.error(e);
  process.exitCode = 1;
});
